export class SessionStore {
  private readonly entries = new Map<string, Entry>();

  constructor(private readonly ttlMs: number, private readonly clock: Clock = Date) {}

  touch(id: string, data: SessionData): void {
    const now = this.clock.now();
    const expiresAt = now + this.ttlMs;
    this.entries.set(id, { data, expiresAt });
  }

  get(id: string): SessionData | undefined {
    const entry = this.entries.get(id);
    if (!entry) return undefined;
    const now = this.clock.now();
    if (entry.expiresAt <= now) {
      this.entries.delete(id);
      return undefined;
    }
    return entry.data;
  }
}

export function startSweeper(store: SessionStore, intervalMs = 60_000): () => void {
  const timer = setInterval(() => sweep(store), intervalMs);
  timer.unref();
  return () => clearInterval(timer);
}
